import type { DemoAnalytics, TrendPoint } from '../types/network';

const round1 = (n: number): number => Math.round(n * 10) / 10;

/**
 * DEMO DATA: a deterministic 24-point series with a simulated incident between 13:00 and 15:00.
 * Generated by formula, not measured from any network.
 * TODO(FastAPI): replace with GET /api/experiments/results (real experiment output from Pandas/NumPy).
 */
const trend: TrendPoint[] = Array.from({ length: 24 }, (_, h): TrendPoint => {
  const incident = h >= 13 && h <= 15;
  const avgLatency = round1(24 + 5 * Math.sin(h / 3.2) + (incident ? 11 : 0));
  return {
    time: `${String(h).padStart(2, '0')}:00`,
    avgLatency,
    peakLatency: round1(avgLatency * 1.6 + (incident ? 8 : 0)),
    availability: incident ? 71.4 : 100,
    quality: round1(incident ? 62 + (h % 3) * 3 : 92 - 3 * Math.sin(h / 2)),
  };
});

export const demoAnalytics: DemoAnalytics = {
  trend,
  baseline: { packetLossPct: 0.4, recoveryTimeS: 1.8 },
};
